    } else if (op === '*') {
      const prev = stack.length > 0 ? stack.pop() : 0;
      stack.push(prev * current);
    } else {
      const prev = stack.length > 0 ? stack.pop() : 0;
      stack.push(Math.trunc(prev / current));
    }
    current = 0;
    building = false;
  }
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch >= '0' && ch <= '9') {
      current = current * 10 + (ch.charCodeAt(0) - 48);
      building = true;
    } else if (ch === '+' || ch === '-' || ch === '*' || ch === '/') {
      apply();
      op = ch;
    }
  }
  apply();
  let total = 0;
  for (let i = 0; i < stack.length; i++) {
    total += stack[i];
  }
  return total;
