            a = values[pos]
            b = values[pos + 1] if pos + 1 < len(values) else 0.0
            result = a * b if operators[pos] == '*' else math.trunc(a / b)
            values[pos:pos + 2] = [result]
            del operators[pos]
        else:
            pos += 1

    total = values[0]
    for i in range(len(operators)):
        next_val = values[i + 1] if i + 1 < len(values) else 0.0
        total = total + next_val if operators[i] == '+' else total - next_val

